def Q(id_, tag, title, quizzes, explain, code=None):
    return dict(kind='mcq', id=id_, tag=tag, title=title, quizzes=quizzes, explain=explain, code=code)
def B(id_, tag, title, q, tokens, why, join=' → '):
    return dict(kind='build', id=id_, mode='order', join=join, tag=tag, title=title, q=q, tokens=tokens, decoys=[], why=why)

